/* OpenLearnHub Global Styles */

:root {
  --primary-dark: #0a0a23;
  --accent-gold: #feac32;
  --link-blue: #002ead;
  --text-main: #1b1b32;
  --text-secondary: #5a5a7a;
  --bg-body: #ffffff;
  --bg-light: #f5f6f7;
  --border-color: #e0e0e0;
  --card-shadow: 0 2px 8px rgba(0,0,0,0.06);
  --radius: 8px;
  --radius-lg: 12px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text-main);
  background: var(--bg-body);
  line-height: 1.6;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

/* Header */
.site-header {
  background: var(--primary-dark);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  gap: 1rem;
}

.logo {
  font-weight: 700;
  font-size: 1.15rem;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  letter-spacing: -0.3px;
}

.logo-mark {
  background: var(--accent-gold);
  color: var(--primary-dark);
  width: 24px;
  height: 24px;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.85rem;
}

.search-bar {
  flex: 1;
  max-width: 420px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 0.9rem 0.5rem 2.2rem;
  border-radius: 4px;
  border: 1px solid #3b3b4f;
  background: #3b3b4f;
  color: #fff;
  font-size: 0.9rem;
  outline: none;
}

.search-bar input::placeholder {
  color: #b0b0c0;
}

.search-bar svg {
  position: absolute;
  left: 0.7rem;
  top: 50%;
  transform: translateY(-50%);
  color: #b0b0c0;
  width: 16px;
  height: 16px;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

.desktop-nav a {
  color: #fff;
  font-size: 0.9rem;
  font-weight: 500;
  opacity: 0.9;
}

.desktop-nav a:hover {
  opacity: 1;
  text-decoration: underline;
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background: #1b1b32;
  padding: 0.75rem 1.25rem;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  color: #fff;
  padding: 0.6rem 0;
  font-size: 0.95rem;
  border-bottom: 1px solid #3b3b4f;
}

.mobile-nav a:last-child {
  border-bottom: none;
}

/* Banner */
.hero-banner {
  background: var(--primary-dark);
  color: #fff;
  text-align: center;
  padding: 0.85rem 1rem;
  font-size: 1rem;
  font-weight: 600;
}

.hero-banner a {
  color: var(--accent-gold);
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Section titles */
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  color: var(--text-main);
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

@media (max-width: 992px) {
  .card-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
  .search-bar {
    display: none;
  }
  .desktop-nav {
    display: none;
  }
  .menu-toggle {
    display: block;
  }
}

.article-card {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
  cursor: pointer;
}

.article-card:hover {
  box-shadow: var(--card-shadow);
  transform: translateY(-2px);
}

.article-card .thumb {
  width: 100%;
  height: 170px;
  object-fit: cover;
  background: var(--bg-light);
}

.article-card .body {
  padding: 1rem;
}

.tag-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 0.5rem;
}

.tag-ai { color: #c0392b; }
.tag-web-scraping { color: #2980b9; }
.tag-databases { color: #27ae60; }
.tag-elasticsearch { color: #8e44ad; }
.tag-data-engineering { color: #d35400; }
.tag-python { color: #2c3e50; }
.tag-node-js { color: #16a085; }
.tag-google-sheets { color: #27ae60; }
.tag-ai-automation { color: #c0392b; }
.tag-tech { color: #2980b9; }
.tag-startup { color: #8e44ad; }
.tag-design { color: #d35400; }
.tag-productivity { color: #27ae60; }
.tag-css { color: #2980b9; }
.tag-javascript { color: #f1c40f; }
.tag-react { color: #61dafb; }
.tag-general-programming { color: #2c3e50; }
.tag-web-development { color: #8e44ad; }
.tag-youtube { color: #c0392b; }
.tag-software-development { color: #16a085; }
.tag-life-lessons { color: #d35400; }
.tag-self-improvement { color: #27ae60; }

.article-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 0.75rem;
  color: var(--text-main);
}

.meta {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.meta .avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-light);
  object-fit: cover;
}

/* Featured card */
.featured-section {
  padding: 2rem 0 1rem;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 320px;
  display: flex;
  align-items: flex-end;
}

.featured-card .featured-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-card .overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10,10,35,0.85) 0%, rgba(10,10,35,0.2) 60%, transparent 100%);
}

.featured-card .content {
  position: relative;
  padding: 2rem;
  color: #fff;
  max-width: 700px;
}

.featured-card .tag-label {
  background: var(--accent-gold);
  color: var(--primary-dark);
  padding: 0.25rem 0.6rem;
  border-radius: 4px;
  font-size: 0.7rem;
  margin-bottom: 0.75rem;
}

.featured-card h2 {
  font-size: 1.6rem;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 1rem;
}

.featured-card .meta {
  color: rgba(255,255,255,0.85);
}

/* Load more */
.load-more {
  text-align: center;
  margin: 2rem 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.7rem 1.5rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  border: 2px solid var(--primary-dark);
  background: var(--primary-dark);
  color: #fff;
  transition: background 0.2s, color 0.2s;
}

.btn:hover {
  background: transparent;
  color: var(--primary-dark);
  text-decoration: none;
}

.btn-outline {
  background: transparent;
  color: var(--primary-dark);
}

.btn-outline:hover {
  background: var(--primary-dark);
  color: #fff;
}

.btn-gold {
  background: var(--accent-gold);
  border-color: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-gold:hover {
  background: transparent;
  color: var(--primary-dark);
}

/* Footer */
.site-footer {
  background: var(--bg-light);
  border-top: 1px solid var(--border-color);
  padding: 2.5rem 0 2rem;
  margin-top: 3rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-col h4 {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.75rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.footer-links a:hover {
  color: var(--text-main);
}

/* Donate page */
.donate-hero {
  background: var(--primary-dark);
  color: #fff;
  padding: 3rem 0;
}

.donate-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 1rem;
}

.donate-hero p {
  max-width: 640px;
  line-height: 1.6;
  opacity: 0.9;
}

.donation-form {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  max-width: 560px;
  margin: -2rem auto 2rem;
  box-shadow: var(--card-shadow);
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.amount-tab {
  flex: 1;
  padding: 0.6rem 0;
  border: 2px solid var(--border-color);
  border-radius: var(--radius);
  background: var(--bg-body);
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  text-align: center;
  transition: border-color 0.2s, background 0.2s;
}

.amount-tab.active {
  border-color: var(--accent-gold);
  background: rgba(254,172,50,0.08);
}

.donation-desc {
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
  line-height: 1.5;
}

.donation-desc strong {
  color: var(--text-main);
}

.donate-btn-wrap {
  text-align: center;
}

.donate-btn-wrap .btn {
  width: 100%;
  padding: 0.85rem;
  font-size: 1.05rem;
}

.donate-sub {
  text-align: center;
  margin-top: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

/* Benefits / Initiatives / Achievements */
.info-section {
  padding: 2.5rem 0;
}

.info-section.alt {
  background: var(--bg-light);
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.5rem;
}

.info-card {
  background: var(--bg-body);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.5rem;
}

.info-card h4 {
  font-size: 1.05rem;
  margin-bottom: 0.75rem;
}

.info-card ul {
  padding-left: 1.2rem;
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.info-card li {
  margin-bottom: 0.4rem;
}

/* FAQ */
.faq-list {
  max-width: 800px;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-main);
}

.faq-question svg {
  width: 18px;
  height: 18px;
  transition: transform 0.25s;
  flex-shrink: 0;
  margin-left: 0.5rem;
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1rem;
}

/* Learn page */
.welcome-cta {
  background: var(--bg-light);
  padding: 2rem 0;
  text-align: center;
}

.welcome-cta p {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.curriculum-section {
  padding: 2.5rem 0;
}

.cert-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1rem;
}

.cert-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  background: var(--bg-body);
  transition: box-shadow 0.2s;
}

.cert-item:hover {
  box-shadow: var(--card-shadow);
}

.cert-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  background: var(--bg-light);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}

.cert-item span {
  font-weight: 600;
  font-size: 0.95rem;
}

.challenge-box {
  background: var(--primary-dark);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
}

.challenge-box h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.challenge-box a {
  color: var(--accent-gold);
  font-weight: 600;
  margin: 0 0.5rem;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  .two-col {
    grid-template-columns: 1fr;
  }
}

/* Tag pages */
.tag-header {
  padding: 2rem 0 1rem;
}

.tag-header h1 {
  font-size: 1.8rem;
  font-weight: 800;
}

.tag-header p {
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

.popular-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.4rem 0.75rem;
  border-radius: 4px;
  background: var(--bg-light);
  border: 1px solid var(--border-color);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-main);
  transition: background 0.2s;
}

.popular-tag:hover {
  background: var(--border-color);
  text-decoration: none;
}

.popular-tag .count {
  color: var(--text-secondary);
  font-size: 0.8rem;
}

/* Utilities */
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

(function () {
  'use strict';

  // Mobile menu toggle
  const menuToggle = document.getElementById('menu-toggle');
  const mobileNav = document.getElementById('mobile-nav');
  if (menuToggle && mobileNav) {
    menuToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('open');
      const expanded = mobileNav.classList.contains('open');
      menuToggle.setAttribute('aria-expanded', expanded);
    });
  }

  // Donation amount tabs
  const amountTabs = document.querySelectorAll('.amount-tab');
  const donationDesc = document.getElementById('donation-desc');
  const donateSub = document.getElementById('donate-sub');

  if (amountTabs.length && donationDesc) {
    const impacts = {
      5: 'Your $5 donation will provide 250 hours of learning to people around the world each month.',
      10: 'Your $10 donation will provide 500 hours of learning to people around the world each month.',
      20: 'Your $20 donation will provide 1,000 hours of learning to people around the world each month.',
      40: 'Your $40 donation will provide 2,000 hours of learning to people around the world each month.'
    };

    amountTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        amountTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        const amount = parseInt(tab.dataset.amount, 10);
        donationDesc.innerHTML = impacts[amount] || '';
        if (donateSub) {
          donateSub.textContent = `Donating $${amount} / month: edit amount · Secure donation`;
        }
      });
    });
  }

  // FAQ accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (!question) return;
    question.addEventListener('click', () => {
      const isOpen = item.classList.contains('open');
      // Close all others (optional accordion behavior)
      faqItems.forEach(i => i.classList.remove('open'));
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });

  // Load more articles
  const loadMoreBtn = document.getElementById('load-more-btn');
  const articleGrid = document.getElementById('article-grid');

  if (loadMoreBtn && articleGrid) {
    const extraArticles = [
      {
        tag: '#JavaScript',
        tagClass: 'tag-javascript',
        title: 'Understanding Closures in JavaScript: A Practical Guide',
        author: 'Sarah Chen',
        time: '2 days ago',
        thumb: 'https://images.unsplash.com/photo-1579468118864-1b9ea3c0db4a?w=600&h=340&fit=crop'
      },
      {
        tag: '#React',
        tagClass: 'tag-react',
        title: 'React Server Components: What You Need to Know in 2025',
        author: 'Michael Park',
        time: '3 days ago',
        thumb: 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=600&h=340&fit=crop'
      },
      {
        tag: '#Python',
        tagClass: 'tag-python',
        title: 'Async Python: Writing High-Performance I/O Bound Applications',
        author: 'Aisha Patel',
        time: '4 days ago',
        thumb: 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=600&h=340&fit=crop'
      },
      {
        tag: '#CSS',
        tagClass: 'tag-css',
        title: 'Modern CSS Layouts: Grid, Flexbox, and Container Queries',
        author: 'Lucas Meyer',
        time: '5 days ago',
        thumb: 'https://images.unsplash.com/photo-1507721999472-8ed4421c4af2?w=600&h=340&fit=crop'
      },
      {
        tag: '#tech',
        tagClass: 'tag-tech',
        title: 'The State of Developer Tools in 2025',
        author: 'Emily Zhao',
        time: '6 days ago',
        thumb: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=600&h=340&fit=crop'
      },
      {
        tag: '#startup',
        tagClass: 'tag-startup',
        title: 'From Side Project to Startup: Lessons from Bootstrapped Founders',
        author: 'David Okafor',
        time: '1 week ago',
        thumb: 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=600&h=340&fit=crop'
      }
    ];

    loadMoreBtn.addEventListener('click', () => {
      extraArticles.forEach(art => {
        const card = document.createElement('article');
        card.className = 'article-card';
        card.innerHTML = `
          <img class="thumb" src="${art.thumb}" alt="" loading="lazy">
          <div class="body">
            <span class="tag-label ${art.tagClass}">${art.tag}</span>
            <h3>${art.title}</h3>
            <div class="meta">
              <img class="avatar" src="https://ui-avatars.com/api/?name=${encodeURIComponent(art.author)}&background=random&size=64" alt="${art.author}">
              <span>${art.author}</span>
              <span>·</span>
              <span>${art.time}</span>
            </div>
          </div>
        `;
        articleGrid.appendChild(card);
      });
      loadMoreBtn.style.display = 'none';
    });
  }
})();
